import app from 'flarum/forum/app';
import Alert from 'flarum/common/components/Alert';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import { extend } from 'flarum/common/extend';
import { PUSH_PERMISSION_REQUEST, PUSH_PERMISSION_STATE, PUSH_TOKEN, requestPushPermissions, requestPushPermissionState, requestPushToken, usingAppleWebview } from './appleWebView';
const AUTHORIZED_STATES = ['authorized', 'ephemeral', 'provisional', 'granted'];
let permissionState;
let listenersRegistered = false;
function isAuthorized(state) {
  return AUTHORIZED_STATES.includes(state);
}
function handlePushPermissionRequest(event) {
  const state = event.detail;
  permissionState = state;
  if (isAuthorized(state)) {
    requestPushToken();
  }
  m.redraw();
}
function handlePushPermissionState(event) {
  const state = event.detail;
  permissionState = state;
  if (isAuthorized(state)) {
    requestPushToken();
  }
  m.redraw();
}
function handlePushToken(event) {
  const token = event.detail;
  void app.request({
    method: 'POST',
    url: `${app.forum.attribute('apiUrl')}/pwa/firebase_push_subscriptions`,
    body: {
      data: {
        attributes: {
          token
        }
      }
    }
  }).catch(error => {
    console.error('[fof-pwa] Firebase push token sync failed:', error);
  });
}
function registerListeners() {
  if (!usingAppleWebview() || listenersRegistered) return;
  listenersRegistered = true;
  window.addEventListener(PUSH_PERMISSION_REQUEST, handlePushPermissionRequest);
  window.addEventListener(PUSH_PERMISSION_STATE, handlePushPermissionState);
  window.addEventListener(PUSH_TOKEN, handlePushToken);
  requestPushPermissionState();
}
function removeListeners() {
  if (!listenersRegistered) return;
  listenersRegistered = false;
  window.removeEventListener(PUSH_PERMISSION_REQUEST, handlePushPermissionRequest);
  window.removeEventListener(PUSH_PERMISSION_STATE, handlePushPermissionState);
  window.removeEventListener(PUSH_TOKEN, handlePushToken);
}
export default function addFirebasePushNotifications() {
  extend('flarum/forum/components/SettingsPage', 'notificationsItems', function (items) {
    if (!usingAppleWebview() || permissionState === undefined || isAuthorized(permissionState)) return;
    items.add('firebase-push-optin-default', m(Alert, {
      dismissible: false,
      className: "pwa-setting-alert",
      controls: [m(Button, {
        className: "Button Button--link",
        onclick: requestPushPermissions
      }, app.translator.trans('fof-pwa.forum.settings.pwa_notifications.access_default_button'))]
    }, m(Icon, {
      name: "fas fa-exclamation-circle"
    }), app.translator.trans('fof-pwa.forum.settings.pwa_notifications.access_default')), 10);
  });
  extend('flarum/forum/components/SettingsPage', 'oncreate', function () {
    registerListeners();
  });
  extend('flarum/forum/components/SettingsPage', 'onremove', function () {
    removeListeners();
  });
}
flarum.reg.add('fof-pwa', 'forum/native/addFirebasePushNotifications', addFirebasePushNotifications);